function nombreSubcuentaFp(id) {
  const s = STATE_fpDesgloseCatalogos.subcuentas.find(x => x.id === id);
  return s ? s.nombre : '(cuenta eliminada)';
}
function renderFpDesgloseList() {
  const box = document.getElementById('fpDesgloseList');
  const total = STATE_fpDesgloseLineas.reduce((s,l)=>s+(Number(l.monto)||0),0);
  const esFiscalConIva = biz()?.modo === 'fiscal_contable' && document.getElementById('fpAplicaIva').checked;
  const importe = esFiscalConIva
    ? (leerMonto(document.getElementById('fpSubtotal').value) || 0)
    : (leerMonto(document.getElementById('fpImporte').value) || 0);
  const cuadra = Math.abs(total - importe) < 0.5;
  box.innerHTML = STATE_fpDesgloseLineas.map((l, i) => `
    <div style="display:flex;align-items:center;justify-content:space-between;padding:6px 2px;border-bottom:1px solid var(--line);font-size:12.5px;">
      <span>${nombreSubcuentaFp(l.subcuenta_id)}${l.descripcion?' — '+l.descripcion:''}</span>
      <span style="display:flex;align-items:center;gap:8px;">
        <strong>${fmt(l.monto)}</strong>
        <button class="fp-desglose-editar" data-idx="${i}" style="border:none;background:none;color:var(--navy-3);cursor:pointer;font-size:12px;text-decoration:underline;">Editar</button>
        <button class="fp-desglose-quitar" data-idx="${i}" style="border:none;background:none;color:var(--red);cursor:pointer;">✕</button>
      </span>
    </div>`).join('');
  document.getElementById('fpDesgloseResumen').innerHTML = `
    <div style="display:flex;justify-content:space-between;"><span>${esFiscalConIva ? 'Subtotal (sin IVA)' : 'Importe de la factura'}</span><strong>${fmt(importe)}</strong></div>
    <div style="display:flex;justify-content:space-between;"><span>Total desglosado</span><strong>${fmt(total)}</strong></div>
    <div style="display:flex;justify-content:space-between;color:${cuadra?'var(--green)':'var(--muted)'};font-weight:700;"><span>${cuadra?'✓ Cuadra':'Diferencia'}</span><span>${cuadra?'':fmt(Math.abs(total-importe))}</span></div>
    ${esFiscalConIva ? `<p style="font-size:11px;color:var(--muted);margin-top:4px;">El IVA no se desglosa aquí — va directo a "IVA Acreditable" en el Balance General, aparte del gasto.</p>` : ''}
  `;
  box.querySelectorAll('.fp-desglose-editar').forEach(btn => btn.addEventListener('click', () => {
    const l = STATE_fpDesgloseLineas[Number(btn.dataset.idx)];
    STATE_fpDesgloseEditandoIdx = Number(btn.dataset.idx);
    document.getElementById('fpDesgloseSubcuenta').value = l.subcuenta_id;
    document.getElementById('fpDesgloseImporte').value = l.importe ? fmtInputVal(l.importe) : '';
    document.getElementById('fpDesgloseIva').value = l.iva ? fmtInputVal(l.iva) : '';
    document.getElementById('fpDesgloseMonto').value = fmtInputVal(l.monto);
    document.getElementById('fpDesgloseDescripcion').value = l.descripcion || '';
    document.getElementById('fpDesgloseEditandoAviso').style.display = '';
    document.getElementById('fpCancelarEdicionDesglose').style.display = '';
    document.getElementById('fpAgregarDesgloseLinea').textContent = 'Guardar cambios';
  }));
  box.querySelectorAll('.fp-desglose-quitar').forEach(btn => btn.addEventListener('click', () => {
    STATE_fpDesgloseLineas.splice(Number(btn.dataset.idx), 1);
    renderFpDesgloseList();
  }));
}
function limpiarFormFpDesglose() {
  document.getElementById('fpDesgloseImporte').value = '';
  document.getElementById('fpDesgloseIva').value = '';
  document.getElementById('fpDesgloseMonto').value = '';
  document.getElementById('fpDesgloseDescripcion').value = '';
  document.getElementById('fpDesgloseEditandoAviso').style.display = 'none';
  document.getElementById('fpCancelarEdicionDesglose').style.display = 'none';
  document.getElementById('fpAgregarDesgloseLinea').textContent = '+ Agregar línea';
}
document.getElementById('fpAgregarDesgloseLinea').addEventListener('click', () => {
  const subId = document.getElementById('fpDesgloseSubcuenta').value;
  const importe = leerMonto(document.getElementById('fpDesgloseImporte').value);
  const iva = leerMonto(document.getElementById('fpDesgloseIva').value);
  const montoDirecto = leerMonto(document.getElementById('fpDesgloseMonto').value);
  const monto = montoDirecto || (importe + iva);
  const descripcion = document.getElementById('fpDesgloseDescripcion').value.trim() || null;
  if (!subId || !monto) { toast('Selecciona subcuenta y captura un monto (o Importe + IVA).', 'error'); return; }
  const nuevaLinea = { subcuenta_id: subId, monto, descripcion, importe: importe || null, iva: iva || null };
  if (STATE_fpDesgloseEditandoIdx !== null) STATE_fpDesgloseLineas[STATE_fpDesgloseEditandoIdx] = nuevaLinea;
  else STATE_fpDesgloseLineas.push(nuevaLinea);
  STATE_fpDesgloseEditandoIdx = null;
  limpiarFormFpDesglose();
  renderFpDesgloseList();
});
document.getElementById('fpCancelarEdicionDesglose').addEventListener('click', () => {
  STATE_fpDesgloseEditandoIdx = null;
  limpiarFormFpDesglose();
});
const fpSumarImporteIva = () => {
  const importe = leerMonto(document.getElementById('fpDesgloseImporte').value);
  const iva = leerMonto(document.getElementById('fpDesgloseIva').value);
  if (importe || iva) document.getElementById('fpDesgloseMonto').value = fmtInputVal(importe + iva);
  renderFpDesgloseList();
};
document.getElementById('fpDesgloseImporte').addEventListener('input', fpSumarImporteIva);
document.getElementById('fpDesgloseIva').addEventListener('input', fpSumarImporteIva);
document.getElementById('fpDesgloseMonto').addEventListener('input', renderFpDesgloseList);
document.getElementById('fpImporte').addEventListener('input', renderFpDesgloseList);
document.getElementById('saveFacturaProveedor').addEventListener('click', async () => {
  const b = biz();
  if (!b) return;
  const fechaFp = document.getElementById('fpFecha').value || todayStr();
  if (await bloqueadoPorCierre(b.id, fechaFp)) return;
  const proveedor_id = document.getElementById('fpProveedor').value || null;
  const catOption = document.getElementById('fpProveedor').selectedOptions[0];
  let proveedorTexto = proveedor_id ? catOption.textContent : (catOption?.textContent || 'Nuevo proveedor');
  if (!proveedor_id && proveedorTexto === '— elegir —') proveedorTexto = 'Nuevo proveedor';
  const esFiscalContable = biz()?.modo === 'fiscal_contable';
  const monedaFp = document.getElementById('fpMoneda').value;
  const tipoCambioFp = monedaFp === 'MXN' ? 1 : (leerMonto(document.getElementById('fpTipoCambio').value) || 1);
  const payload = {
    business_id: b.id,
    proveedor_id,
    proveedor: proveedorTexto,
    factura: document.getElementById('fpFactura').value.trim() || null,
    fecha: fechaFp,
    fecha_vencimiento: document.getElementById('fpVencimiento').value || null,
    moneda: monedaFp, tipo_cambio: tipoCambioFp,
    importe: leerMonto(document.getElementById('fpImporte').value) || 0,
    estatus: document.getElementById('fpEstatus').value,
    fecha_pago: document.getElementById('fpFechaPago').value || null,
    desglose: STATE_fpDesgloseLineas,
    subtotal: esFiscalContable ? (leerMonto(document.getElementById('fpSubtotal').value) || 0) : null,
    aplica_iva: esFiscalContable ? document.getElementById('fpAplicaIva').checked : false,
    iva_porcentaje: esFiscalContable ? (leerMonto(document.getElementById('fpIvaPorcentaje').value) || 0) : null,
    iva_monto: esFiscalContable ? (leerMonto(document.getElementById('fpIvaMonto').value) || 0) : 0,
    aplica_retencion: esFiscalContable ? document.getElementById('fpAplicaRetencion').checked : false,
    retencion_categoria: esFiscalContable ? (document.getElementById('fpRetencionCategoria').value || null) : null,
    retencion_isr_porcentaje: esFiscalContable ? (leerMonto(document.getElementById('fpRetencionIsrPct').value) || 0) : 0,
    retencion_isr_monto: esFiscalContable ? (leerMonto(document.getElementById('fpRetencionIsrMonto').value) || 0) : 0,
    retencion_iva_porcentaje: esFiscalContable ? (leerMonto(document.getElementById('fpRetencionIvaPct').value) || 0) : 0,
    retencion_iva_monto: esFiscalContable ? (leerMonto(document.getElementById('fpRetencionIvaMonto').value) || 0) : 0,
  };
  const pagadoDesde = document.getElementById('fpPagadoDesde').value;
  if (pagadoDesde) {
    const [tipo, cuentaId] = pagadoDesde.split(':');
    payload.pagado_desde_tipo = tipo;
    payload.pagado_desde_cuenta_id = cuentaId;
  } else {
    payload.pagado_desde_tipo = null;
    payload.pagado_desde_cuenta_id = null;
  }

  const idEditando = STATE_facturaProveedorEditandoId;
  let facturaId = idEditando;
  if (idEditando) {
    const { error } = await sb.from('fz_proveedores').update(payload).eq('id', idEditando);
    if (error) { toast('Error: ' + error.message, 'error'); return; }
  } else {
    payload.folio = await siguienteFolio(b.id, 'factura_proveedor');
    const { data, error } = await sb.from('fz_proveedores').insert(payload).select().single();
    if (error) { toast('Error: ' + error.message, 'error'); return; }
    facturaId = data.id;
    for (const file of STATE_provArchivosPendientes) {
      const subido = await subirAdjunto('fz_proveedores', facturaId, b.id, file);
      if (subido) await sb.from('fz_adjuntos').insert({ business_id: b.id, tabla: 'fz_proveedores', registro_id: facturaId, archivo_path: subido.path, archivo_nombre: subido.nombre });
    }
    STATE_provArchivosPendientes = [];
  }

  // Activo Fijo vinculado a esta factura
  const esActivoFijo = document.getElementById('fpEsActivoFijo').checked;
  if (esActivoFijo) {
    // Costo contable: NUNCA el total con IVA. Si la factura tiene desglose fiscal capturado
    // (subtotal/iva_monto separados), el costo es el subtotal — el IVA se conserva aparte, solo
    // como referencia. Si no hay desglose fiscal, no existe una base separable y se usa el
    // importe tal cual (no hay otro dato del que partir). Regla dinámica — nunca un monto fijo.
    const tieneDesgloseFiscal = payload.subtotal !== null && payload.subtotal !== undefined && Number(payload.subtotal) > 0;
    const costoContable = tieneDesgloseFiscal ? Number(payload.subtotal) : Number(payload.importe);
    const ivaSeparado = tieneDesgloseFiscal ? Number(payload.iva_monto || 0) : 0;
    const fechaDisponibleUso = document.getElementById('fpAfFechaDisponible').value || payload.fecha;
    const afPayload = {
      business_id: b.id,
      nombre: document.getElementById('fpAfNombre').value.trim() || payload.proveedor,
      categoria: document.getElementById('fpAfCategoria').value || null,
      fecha_adquisicion: payload.fecha,
      fecha_disponible_uso: fechaDisponibleUso,
      costo_adquisicion: costoContable,
      iva_monto: ivaSeparado,
      porcentaje_anual: leerMonto(document.getElementById('fpAfPorcentaje').value) || 0,
      cuenta_gasto_id: document.getElementById('fpAfCuentaGasto').value || null,
      cuenta_depreciacion_id: document.getElementById('fpAfCuentaDepreciacion').value || null,
    };
    if (STATE_fpActivoFijoExistente) {
      await sb.from('fz_activos_fijos').update(afPayload).eq('id', STATE_fpActivoFijoExistente.id);
    } else {
      const { data: nuevoAf, error: errAf } = await sb.from('fz_activos_fijos').insert(afPayload).select().single();
      if (!errAf && nuevoAf) {
        await sb.from('fz_proveedores').update({ activo_fijo_id: nuevoAf.id }).eq('id', facturaId);
        registrarAuditoria(b.id, 'crear', 'Activos Fijos', `${afPayload.nombre} — generado desde factura de proveedor`);
      }
    }
  } else if (STATE_fpActivoFijoExistente) {
    // Se desmarcó: si ya tiene depreciación generada, se conserva (no se pierde el historial),
    // solo se desvincula de esta factura.
    const acumulado = await acumuladoDe(STATE_fpActivoFijoExistente.id);
    if (acumulado <= 0.004) {
      await sb.from('fz_activos_fijos').delete().eq('id', STATE_fpActivoFijoExistente.id);
    }
    await sb.from('fz_proveedores').update({ activo_fijo_id: null }).eq('id', facturaId);
  }

  registrarAuditoria(b.id, idEditando ? 'editar' : 'crear', 'Proveedores', `${payload.proveedor} · factura ${payload.factura||'s/f'} · ${fmt(payload.importe)}`);
  document.getElementById('modalFacturaProveedor').classList.remove('show');
  STATE_facturaProveedorEditandoId = null;
  toast(idEditando ? 'Factura actualizada.' : 'Factura agregada.');
  renderProveedores();
});
document.getElementById('deleteFacturaProveedor').addEventListener('click', async () => {
  const b = biz();
  if (!b || !STATE_facturaProveedorEditandoId) return;
  const r = await eliminarFacturaProveedorConCascada(STATE_facturaProveedorEditandoId, b.id);
  if (!r.ok) return;
  document.getElementById('modalFacturaProveedor').classList.remove('show');
  STATE_facturaProveedorEditandoId = null;
  renderProveedores();
});

function provRowHtml(p, catalogo, opcionesPagoDesde, conteoAdjuntos, todasFacturas) {
  const desgloseTotal = desgloseLineas(p.desglose).reduce((s,l)=>s+(Number(l.monto)||0),0);
  const metaDesglose = p.aplica_iva ? (Number(p.subtotal)||0) : (Number(p.importe)||0);
  const desgloseOk = Math.abs(desgloseTotal - metaDesglose) < 1 && desgloseTotal > 0;
  const esCredito = Number(p.importe) < 0;
  const saldoPendiente = Number(p.importe) - Number(p.importe_pagado || 0);
  const catMatch = p.proveedor_id ? catalogo.find(c => c.id === p.proveedor_id) : null;
  const nombreMostrado = catMatch
    ? (catMatch.razon_social ? `${catMatch.razon_social}${catMatch.nombre_comercial ? ' — ' + catMatch.nombre_comercial : ''}` : (catMatch.nombre_comercial || catMatch.nombre))
    : (p.proveedor || '(sin proveedor)');
  const esMxnProv = !p.moneda || p.moneda === 'MXN';
  return `<tr style="${esCredito?'background:#f2fbf5;':''}">
    <td data-rol="principal"><input class="cell prov-cell" type="date" value="${p.fecha}" data-id="${p.id}" data-field="fecha"></td>
    <td data-rol="secundario">${p.folio ? '#'+p.folio : '—'}</td>
    <td data-rol="secundario"><input class="cell prov-cell" type="text" value="${p.factura||''}" data-id="${p.id}" data-field="factura"></td>
    <td data-rol="secundario">${nombreMostrado}</td>
    <td data-rol="meta">${p.moneda || 'MXN'}</td>
    <td class="num" data-rol="meta">${esMxnProv ? '—' : fmtTC(p.tipo_cambio || 1)}</td>
    <td data-rol="importe">
      <input class="cell prov-cell num num-fmt" type="text" inputmode="decimal" value="${fmtInputVal(p.importe)}" data-id="${p.id}" data-field="importe">
      ${esCredito ? `<div style="font-size:10.5px;color:var(--green);margin-top:2px;">crédito a favor</div>` : ''}
    </td>
    <td class="num" data-rol="meta">${prefijoMoneda(p.moneda)} ${fmt(p.importe_pagado||0)}</td>
    <td class="num" data-rol="meta" style="${saldoPendiente>0.004?'color:var(--gold);font-weight:600;':''}">${prefijoMoneda(p.moneda)} ${fmt(saldoPendiente)}</td>
    <td data-rol="meta">${p.fecha_vencimiento ? fechaCorta(p.fecha_vencimiento) : '—'}</td>
    <td data-rol="meta" style="${(() => { const d = calcularDiasRetraso(p.fecha_vencimiento, saldoPendiente); return typeof d==='number' && d>0 ? 'color:var(--red);font-weight:700;' : ''; })()}">${calcularDiasRetraso(p.fecha_vencimiento, saldoPendiente)}</td>
    <td data-rol="meta"><button class="btn btn-ghost btn-sm prov-desglosar" data-id="${p.id}" style="color:${desgloseOk?'var(--green)':(desgloseTotal>0?'var(--red)':'var(--muted)')};" title="${p.aplica_iva?'No incluye IVA — el IVA ('+fmt(p.iva_monto)+') va aparte, a IVA Acreditable':''}">${desgloseTotal<=0?'Desglosar':(desgloseOk?'✓ Completo':`Falta ${fmt(Math.abs(desgloseTotal-metaDesglose))}`)}</button></td>
    <td data-rol="estado"><select class="cell prov-cell" data-id="${p.id}" data-field="estatus">
      <option ${p.estatus==='Pendiente'?'selected':''}>Pendiente</option>
      <option ${p.estatus==='Parcial'?'selected':''}>Parcial</option>
      <option ${p.estatus==='Pagado'?'selected':''}>Pagado</option>
    </select></td>
    <td data-rol="meta"><input class="cell prov-cell" type="date" value="${p.fecha_pago||''}" data-id="${p.id}" data-field="fecha_pago"></td>
    <td data-rol="meta"><select class="cell prov-pagodesde" data-id="${p.id}" style="min-width:150px;">
      <option value="">— sin especificar —</option>
      ${opcionesPagoDesde.map(o => `<option value="${o.value}" ${(p.pagado_desde_tipo && (p.pagado_desde_tipo+':'+p.pagado_desde_cuenta_id)===o.value)?'selected':''}>${o.label}</option>`).join('')}
    </select></td>
    <td data-rol="meta">${adjuntosCellHtml(conteoAdjuntos, p.id)}</td>
    <td data-rol="acciones" style="position:relative;">
      <button class="btn btn-ghost btn-sm prov-menu-btn" data-id="${p.id}" style="padding:5px 12px;">⋯</button>
      <div class="prov-menu-dropdown" data-menu="${p.id}" style="display:none;position:absolute;right:8px;top:100%;background:#fff;border:1px solid var(--line);border-radius:8px;box-shadow:0 4px 16px rgba(0,0,0,.14);z-index:20;min-width:130px;overflow:hidden;">
        <button class="prov-editar" data-id="${p.id}" style="display:block;width:100%;text-align:left;padding:9px 14px;border:none;background:none;cursor:pointer;font-size:13px;">Editar factura</button>
        <button class="prov-del" data-id="${p.id}" style="display:block;width:100%;text-align:left;padding:9px 14px;border:none;background:none;cursor:pointer;font-size:13px;color:var(--red);border-top:1px solid var(--line);">Eliminar</button>
      </div>
    </td>
  </tr>`;
}

/* ============================================================
   P&L — ESTADO DE RESULTADOS
   ============================================================ */
let STATE_plVista = 'mensual'; // 'mensual' | 'acumulado' | 'anual'
let STATE_plComparacion = 'ninguna'; // 'ninguna' | 'anterior' | 'anioAnterior'
let STATE_plRangoDesde = '';
let STATE_plRangoHasta = '';
let STATE_plAnualDesdeYm = ''; // 'YYYY-MM', vacío = enero del año actual
let STATE_plAnualHastaYm = ''; // 'YYYY-MM', vacío = diciembre del año actual
let STATE_plAnualModo = 'detalle'; // 'detalle' | 'ejecutivo'
let STATE_plDetalleAbierto = null; // subcuenta id cuyo detalle está desplegado

function periodoPL(ym, vista) {
  const { start, end } = monthBounds(ym);
  if (vista === 'acumulado') {
    const year = ym.slice(0, 4);
    return { start: `${year}-01-01`, end, mesStart: `${year}-01`, mesEnd: ym };
  }
  return { start, end, mesStart: ym, mesEnd: ym };
}

async function getPolizasLineasPeriodo(businessId, periodo) {
  const { start, end } = periodo;
  const { data: polizas } = await sb.from('fz_polizas').select('id').eq('business_id', businessId).gte('fecha', start).lte('fecha', end);
  const ids = (polizas || []).map(p => p.id);
  if (!ids.length) return [];
  const { data: lineas } = await sb.from('fz_polizas_lineas').select('cargo,abono,subcuenta_id').in('poliza_id', ids);
  return lineas || [];
}

async function getPolizaLineasParaCuenta(businessId, tipo, refId, hastaFecha) {
  const { data: lineas } = await sb.from('fz_polizas_lineas').select('*').eq('business_id', businessId).eq('cuenta_tipo', tipo).eq('cuenta_ref_id', refId);
  if (!lineas || !lineas.length) return [];
  const polizaIds = [...new Set(lineas.map(l => l.poliza_id))];
  const { data: polizas } = await sb.from('fz_polizas').select('id,fecha,concepto,numero').in('id', polizaIds);
  const polizaMap = Object.fromEntries((polizas || []).map(p => [p.id, p]));
  return lineas.map(l => ({ ...l, poliza: polizaMap[l.poliza_id] })).filter(l => l.poliza && (!hastaFecha || l.poliza.fecha <= hastaFecha));
}

function construirArbolSubcuenta(subcuentaId, subcuentas, porSubcuenta, visitados = new Set()) {
  const sub = subcuentas.find(s => s.id === subcuentaId);
  if (visitados.has(subcuentaId)) return { id: subcuentaId, nombre: sub ? sub.nombre : '(eliminada)', propio: porSubcuenta[subcuentaId] || 0, hijos: [], total: porSubcuenta[subcuentaId] || 0 };
  visitados.add(subcuentaId);
  const hijos = subcuentasHijas(subcuentaId, subcuentas).map(h => construirArbolSubcuenta(h.id, subcuentas, porSubcuenta, visitados));
  const propio = porSubcuenta[subcuentaId] || 0;
  const total = propio + hijos.reduce((s,h)=>s+h.total,0);
  return { id: subcuentaId, nombre: sub ? sub.nombre : '(eliminada)', propio, hijos, total };
}
function aplanarArbol(nodo) {
  return [nodo, ...nodo.hijos.flatMap(aplanarArbol)];
}
// Copia filtrada de un árbol de subcuenta, excluyendo los nodos que NO cumplan el predicado
// (por nombre) — nunca muta el árbol original. Usado solo para presentación (separar un renglón
// específico, como "Ingresos financieros", hacia otra sección del Estado de Resultados).
function filtrarNodoArbol(nodo, predicado) {
  const hijosFiltrados = nodo.hijos.map(h => filtrarNodoArbol(h, predicado)).filter(Boolean);
  const propioIncluido = predicado(nodo) ? nodo.propio : 0;
  const total = propioIncluido + hijosFiltrados.reduce((s,h)=>s+h.total,0);
  if (!predicado(nodo) && !hijosFiltrados.length) return null;
  return { ...nodo, propio: propioIncluido, hijos: hijosFiltrados, total };
}

/* ============================================================
   BALANCE GENERAL — Activo = Pasivo + Capital
   ============================================================ */
async function computeSaldoCuentaMayorPolizas(businessId, cuentaMayorId, subcuentas, signoNormal, hastaFecha) {
  // signoNormal 'debe' (Activo): Cargo aumenta, Abono disminuye.
  // signoNormal 'haber' (Pasivo/Capital): Abono aumenta, Cargo disminuye.
  const subs = subcuentas.filter(s => s.cuenta_mayor_id === cuentaMayorId);
  if (!subs.length) return { subs: [], total: 0 };
  const subIds = new Set(subs.map(s => s.id));
  const [lineasQ, facturasQ] = await Promise.all([
    sb.from('fz_polizas_lineas').select('cargo,abono,subcuenta_id,poliza_id').eq('business_id', businessId).eq('cuenta_tipo', 'subcuenta').in('subcuenta_id', subs.map(s => s.id)),
    sb.from('fz_proveedores').select('fecha,desglose,origen_poliza_id').eq('business_id', businessId),
  ]);
  let lineas = lineasQ.data || [];
  if (hastaFecha && lineas.length) {
    const polizaIds = [...new Set(lineas.map(l => l.poliza_id))];
    const { data: polizas } = await sb.from('fz_polizas').select('id,fecha').in('id', polizaIds).lte('fecha', hastaFecha);
    const idsValidos = new Set((polizas || []).map(p => p.id));
    lineas = lineas.filter(l => idsValidos.has(l.poliza_id));
  }
  const porSub = {};
  lineas.forEach(l => {
    const neto = signoNormal === 'debe' ? (Number(l.cargo) || 0) - (Number(l.abono) || 0) : (Number(l.abono) || 0) - (Number(l.cargo) || 0);
    porSub[l.subcuenta_id] = (porSub[l.subcuenta_id] || 0) + neto;
  });
  // Facturas de Proveedores desglosadas contra alguna de estas subcuentas también cuentan
  // (ej. una compra que se clasificó como Activo en vez de Gasto) — antes solo se veían
  // en Proveedores/P&L, nunca llegaban al Balance General. Se excluyen las que vienen de una
  // provisión de póliza, ya que esa misma línea de la póliza ya se contó arriba.
  (facturasQ.data || []).filter(f => !f.origen_poliza_id && (!hastaFecha || f.fecha <= hastaFecha)).forEach(f => {
    desgloseLineas(f.desglose).forEach(linea => {
      if (subIds.has(linea.subcuenta_id) && Number(linea.monto)) {
        const monto = Number(linea.monto);
        porSub[linea.subcuenta_id] = (porSub[linea.subcuenta_id] || 0) + (signoNormal === 'debe' ? monto : -monto);
      }
    });
  });
  const raices = subcuentasRaiz(cuentaMayorId, subcuentas).map(s => construirArbolSubcuenta(s.id, subcuentas, porSub)).filter(s => Math.abs(s.total) > 0.004);
  return { subs: raices, total: raices.reduce((s,x)=>s+x.total,0) };
}

async function computeUtilidadAcumulada(businessId, hastaYm) {
  const year = hastaYm.slice(0,4);
  const periodo = { start: `${year}-01-01`, end: monthBounds(hastaYm).end, mesStart: `${year}-01`, mesEnd: hastaYm };
  const [conceptosVenta, conceptos, subcuentas, mayores, conceptosSistema, ventasQ] = await Promise.all([
    loadConceptosVenta(businessId), loadConceptos(businessId), loadSubcuentas(businessId), loadCuentasMayor(businessId), loadConceptosSistema(businessId),
    sb.from('fz_ventas').select('*').eq('business_id', businessId).gte('fecha', periodo.start).lte('fecha', periodo.end),
  ]);
  const v = ventasAfectaFueraDeSuRegistro(businessId) ? (ventasQ.data || []) : [];
  const totalIngresosVentas = conceptosVenta.reduce((s,c) => {
    const monto = v.reduce((ss,r)=>ss+(Number((r.venta_data||{})[c.id])||0),0);
    return s + (c.tipo==='resta'?-monto:monto);
  }, 0);
  const gastosOperativos = v.reduce((s,r)=>s+(Number(r.gastos)||0),0);
  const porCatPL = { efectivo: conceptos.filter(c=>c.categoria==='efectivo'), tarjetas: conceptos.filter(c=>c.categoria==='tarjetas'), bancos: conceptos.filter(c=>c.categoria==='bancos'), cxc: conceptos.filter(c=>c.categoria==='cxc'), propinas: conceptos.filter(c=>c.categoria==='propinas') };
  let diffPeriodo = 0;
  v.forEach(r => { diffPeriodo += computeRowDiffs(r, conceptosVenta, porCatPL, conceptosSistema).difTotal; });
  const faltanteCaja = diffPeriodo>0?diffPeriodo:0;
  const sobranteCaja = diffPeriodo<0?-diffPeriodo:0;
  const datosGC1 = await fetchDatosGastosCostos(businessId, periodo);
  const [gClas, gCostos] = await Promise.all([
    computeGastosClasificados(businessId, periodo, subcuentas, mayores, 'gasto', false, datosGC1),
    computeGastosClasificados(businessId, periodo, subcuentas, mayores, 'costo', false, datosGC1),
  ]);
  const iPoliza = await computeIngresosPoliza(businessId, periodo, subcuentas, mayores);
  const gananciaCambiaria = await computeGananciaCambiaria(businessId, periodo);
  const totalIngresosFinal = totalIngresosVentas + sobranteCaja + iPoliza.total + gananciaCambiaria;
  const gastosTotales = gastosOperativos + gClas.totalClasificado + gClas.sinClasificar + gCostos.totalClasificado + faltanteCaja;
  return totalIngresosFinal - gastosTotales;
}

function fmtNeg(n) {
  return Number(n) < 0 ? `<span style="color:var(--red);">${fmt(n)}</span>` : fmt(n);
}
function fmtSigno(n) {
  return `<span style="color:${Number(n)>=0?'var(--green)':'var(--red)'};">${fmt(n)}</span>`;
}
// Recolecta el id de una subcuenta y todos sus descendientes (hijas, nietas, etc.)
function recolectarSubcuentaIds(subcuentaId, subcuentas, visitados = new Set()) {
  if (visitados.has(subcuentaId)) return []; // protección contra ciclos accidentales (A hija de B, B hija de A)
  visitados.add(subcuentaId);
  const ids = [subcuentaId];
  subcuentasHijas(subcuentaId, subcuentas).forEach(h => ids.push(...recolectarSubcuentaIds(h.id, subcuentas, visitados)));
  return ids;
}

// Auxiliar de cuenta: todos los movimientos (Pólizas + Facturas de Proveedores desglosadas) de una
// o varias subcuentas juntas, en un rango de fechas, con Cargo/Abono separados y saldo corrido.
async function getMovimientosCuenta(businessId, subcuentaIds, startDate, endDate) {
  const calcularFilas = async (hasta) => {
    const { data: lineas } = await sb.from('fz_polizas_lineas').select('*').eq('business_id', businessId).eq('cuenta_tipo', 'subcuenta').in('subcuenta_id', subcuentaIds);
    const polizaIds = [...new Set((lineas||[]).map(l => l.poliza_id))];
    const { data: polizas } = polizaIds.length ? await sb.from('fz_polizas').select('id,fecha,numero,concepto').in('id', polizaIds) : { data: [] };
    const polizaMap = Object.fromEntries((polizas||[]).map(p => [p.id, p]));
    const filas = [];
    (lineas||[]).forEach(l => {
      const p = polizaMap[l.poliza_id];
      if (!p) return;
      if (startDate && p.fecha < startDate) return;
      if (hasta && p.fecha > hasta) return;
      const cargo = Number(l.cargo)||0, abono = Number(l.abono)||0;
      if (!cargo && !abono) return;
      filas.push({ fecha: p.fecha, subcuentaId: l.subcuenta_id, proveedor: l.proveedor || `Póliza #${p.numero ?? ''}`, descripcion: l.descripcion || p.concepto || '—', cargo, abono, origen: { tipo: 'poliza', id: p.id, fecha: p.fecha } });
    });
    const { data: facturas } = await sb.from('fz_proveedores').select('*').eq('business_id', businessId);
    (facturas||[]).forEach(f => {
      if (startDate && f.fecha < startDate) return;
      if (hasta && f.fecha > hasta) return;
      desgloseLineas(f.desglose).forEach(linea => {
        if (subcuentaIds.includes(linea.subcuenta_id) && Number(linea.monto)) {
          filas.push({ fecha: f.fecha, subcuentaId: linea.subcuenta_id, proveedor: f.proveedor || '(sin proveedor)', descripcion: linea.descripcion || f.factura || '(factura)', cargo: Number(linea.monto), abono: 0, origen: { tipo: 'proveedor', id: f.id, fecha: f.fecha } });
        }
      });
    });
    return filas.sort((a,b) => a.fecha.localeCompare(b.fecha) || 0);
  };

  const filas = await calcularFilas(endDate);
  const saldoInicialPorSubcuenta = {};
  subcuentaIds.forEach(id => { saldoInicialPorSubcuenta[id] = 0; });
  let saldoInicial = 0;
  if (startDate) {
    const filasPrevias = await calcularFilas(sumarDias(startDate, -1));
    filasPrevias.forEach(f => {
      saldoInicialPorSubcuenta[f.subcuentaId] = (saldoInicialPorSubcuenta[f.subcuentaId] || 0) + f.cargo - f.abono;
    });
    saldoInicial = Object.values(saldoInicialPorSubcuenta).reduce((s,x)=>s+x,0);
  }
  let saldo = saldoInicial;
  filas.forEach(f => { saldo += f.cargo - f.abono; f.saldo = saldo; });
  return { filas, saldoInicial, saldoFinal: saldo, saldoInicialPorSubcuenta };
}

/* ============================================================
   LIBRO DIARIO UNIFICADO — convierte cada movimiento del sistema
   (Pólizas, Bancos, Efectivo, Facturas de Proveedores/Clientes) al
   mismo formato de Cargo/Abono, para auditorías y revisión completa.
   ============================================================ */
/* ============================================================
   BALANZA DE COMPROBACIÓN — PARTIDA DOBLE
   Reconstruye, para cada cuenta real (identificada por clave estable, no por texto),
   todos los cargos/abonos de cada tipo de movimiento del sistema, igual que el Libro
   Diario, pero conservando la identidad de la cuenta para poder clasificarla por tipo
   y agregar su saldo correctamente a través del tiempo.
   ============================================================ */
async function getLibroPartidaDoble(businessId, hastaFecha) {
  // Envoltorio delgado: consume la misma reconstrucción que ahora usa el diagnóstico de
  // descuadres, para que Balanza y el diagnóstico NUNCA puedan mostrar cifras distintas.
  const { filas, mayores, subcuentas } = await getLibroPartidaDobleConOrigen(businessId, hastaFecha);
  const filasBalanza = filas.map(f => ({ clave: f.clave, nombre: f.cuenta, tipo: f.tipo, fecha: f.fecha, cargo: f.cargo, abono: f.abono }));
  return { filas: filasBalanza, mayores, subcuentas };
}

/* ============================================================
   DIAGNÓSTICO DE DESCUADRES — "Ver origen de la diferencia"
   Reconstruye lo mismo que getLibroPartidaDoble, pero etiquetando cada
   renglón con su documento de origen, para poder agrupar y encontrar
   exactamente qué documento (o par de traspaso) no cuadra internamente.
   Es de solo lectura — nunca modifica nada, nunca corrige nada.
   ============================================================ */
async function getLibroPartidaDobleConOrigen(businessId, hastaFecha, desdeFecha = null) {
  const filas = [];
  const push = (origen, clave, tipo, cargo, abono) => {
    if (!(Number(cargo)||0) && !(Number(abono)||0)) return;
    filas.push({ ...origen, clave, tipo, cargo: Number(cargo)||0, abono: Number(abono)||0 });
  };
  const conDesde = (q) => desdeFecha ? q.gte('fecha', desdeFecha) : q;

  const [subcuentas, mayores, cuentasBanco, monedas, clientes] = await Promise.all([
    loadSubcuentas(businessId), loadCuentasMayor(businessId),
    sb.from('fz_bancos_cuentas').select('*').eq('business_id', businessId).then(r=>r.data||[]),
    sb.from('fz_efectivo_monedas').select('*').eq('business_id', businessId).then(r=>r.data||[]),
    loadClientes(businessId),
  ]);
  const mayorDeSub = (subId) => { const s = subcuentas.find(x=>x.id===subId); return s ? mayores.find(m=>m.id===s.cuenta_mayor_id) : null; };
  const nombreSub = (id) => subcuentas.find(s=>s.id===id)?.nombre || '(cuenta eliminada)';
  const tipoDeSub = (id) => mayorDeSub(id)?.tipo || 'activo';
  const nombreBanco = (id) => cuentasBanco.find(c=>c.id===id)?.nombre || 'Banco';
  const nombreMoneda = (id) => monedas.find(m=>m.id===id)?.nombre || 'Efectivo';
  const nombreCliente = (id) => { const c = clientes.find(x=>x.id===id); return c ? (c.razon_social || c.nombre_comercial) : '(cliente eliminado)'; };
  const { data: negocioRow } = await sb.from('businesses').select('iva_realizacion_desde').eq('id', businessId).maybeSingle();
  const fechaCorteRealizacion = negocioRow?.iva_realizacion_desde || null;
  const esRealizacionActiva = (fecha) => fechaCorteRealizacion && fecha >= fechaCorteRealizacion;

  // 1. Pólizas de Diario — cada póliza es un documento; sus líneas deberían cuadrar entre sí.
  const { data: polizas } = await conDesde(sb.from('fz_polizas').select('id,fecha,numero,concepto').eq('business_id', businessId).lte('fecha', hastaFecha));
  const polizaIds = (polizas||[]).map(p=>p.id);
  const polizaMap = Object.fromEntries((polizas||[]).map(p=>[p.id,p]));
  const { data: lineasPoliza } = polizaIds.length ? await sb.from('fz_polizas_lineas').select('*').in('poliza_id', polizaIds) : { data: [] };
  (lineasPoliza||[]).forEach(l => {
    const p = polizaMap[l.poliza_id];
    if (!p) return;
    const origen = { modulo: 'Póliza de Diario', tipoOrigen: 'poliza', id: p.id, fecha: p.fecha, referencia: `Póliza #${p.numero ?? ''}`, detalle: p.concepto || '' };
    if (l.cuenta_tipo === 'banco') push({ ...origen, cuenta: `Banco: ${nombreBanco(l.cuenta_ref_id)}` }, 'banco:'+l.cuenta_ref_id, 'activo', l.cargo, l.abono);
    else if (l.cuenta_tipo === 'efectivo') push({ ...origen, cuenta: `Efectivo: ${nombreMoneda(l.cuenta_ref_id)}` }, 'efectivo:'+l.cuenta_ref_id, 'activo', l.cargo, l.abono);
    else if (l.cuenta_tipo === 'proveedor' || l.cuenta_tipo === 'proveedor_provision') push({ ...origen, cuenta: 'Proveedores' }, 'proveedores', 'pasivo', l.cargo, l.abono);
    else if (l.cuenta_tipo === 'cliente') push({ ...origen, cuenta: 'Clientes' }, 'clientes', 'activo', l.cargo, l.abono);
    else push({ ...origen, cuenta: nombreSub(l.subcuenta_id) }, 'sub:'+l.subcuenta_id, tipoDeSub(l.subcuenta_id), l.cargo, l.abono);
  });

  // 2. Facturas de Proveedores — Dr [desglose] + Dr IVA Acreditable + Cr Retenciones, Cr Proveedores.
  // Las cuentas "Pendiente"/"Realizado" deben ser subcuentas REALES (no claves de texto sueltas),
  // porque la póliza de reclasificación automática también las referencia por su id real — si no
  // coinciden, Balanza las ve como dos cuentas distintas aunque tengan el mismo nombre.
  const cacheSubRealizacion = {};

  // READ-FIRST: mayores/subcuentas ya se cargaron arriba (loadCuentasMayor/loadSubcuentas, para
  // mayorDeSub/nombreSub) — se reutilizan aquí para resolver cuentas de realización SIN ninguna
  // consulta adicional. Normalización idéntica a la de la base de datos: nombre_normalizado =
  // lower(trim(nombre)) (ver schema.sql). Solo se indexan subcuentas SIN padre, porque
  // obtenerOCrearSubcuentaPorNombre nunca crea subcuentas con padre — no hay ambigüedad posible.
  const normalizarNombreCuenta = (s) => String(s).trim().toLowerCase();
  const mapaMayorPorTipoNombre = new Map();
  mayores.forEach(m => mapaMayorPorTipoNombre.set(m.tipo + '::' + normalizarNombreCuenta(m.nombre), m.id));
  const mapaSubPorMayorNombre = new Map();
  subcuentas.filter(s => !s.subcuenta_padre_id).forEach(s => mapaSubPorMayorNombre.set(s.cuenta_mayor_id + '::' + normalizarNombreCuenta(s.nombre), s.id));

  const subRealizacion = async (nombre, tipo) => {
    // Clave: tipo + nombre. businessId no hace falta incluirlo porque es el mismo parámetro fijo
    // en toda esta reconstrucción (getLibroPartidaDobleConOrigen no mezcla negocios). tipo SÍ debe
    // ir en la clave porque fz_cuentas_mayor es único por (business_id, tipo, nombre_normalizado)
    // — dos tipos distintos con el mismo nombre visible son cuentas mayores distintas en la base
    // de datos, así que cachear solo por nombre podría, en teoría, devolver el id equivocado.
    // padre no aplica: esta función nunca crea subcuentas con padre (siempre nivel superior).
    const key = tipo + '::' + nombre;
    if (key in cacheSubRealizacion) return cacheSubRealizacion[key];

    const nn = normalizarNombreCuenta(nombre);
    const mayorId = mapaMayorPorTipoNombre.get(tipo + '::' + nn);
    if (mayorId) {
      const subId = mapaSubPorMayorNombre.get(mayorId + '::' + nn);
      if (subId) {
        // RESOLVER ≠ CREAR — la cuenta y la subcuenta ya existían en el catálogo cargado al
        // inicio de esta reconstrucción: se resuelve desde memoria, cero requests remotos.
        cacheSubRealizacion[key] = subId;
        return subId;
      }
      // Caso 12: la cuenta mayor ya se conoce, solo falta la subcuenta — crear/resolver
      // ÚNICAMENTE la subcuenta, sin volver a tocar fz_cuentas_mayor (ya existe).
      const id = await obtenerOCrearSubcuentaBajoMayorConocida(businessId, mayorId, nombre);
      mapaSubPorMayorNombre.set(mayorId + '::' + nn, id); // disponible para el resto de esta reconstrucción
      cacheSubRealizacion[key] = id;
      return id;
    }

    // Ni la mayor ni la subcuenta están en el catálogo cargado — autocreación legítima completa,
    // mediante el mecanismo seguro existente (onConflict protege contra duplicados si dos
    // reconstrucciones concurrentes detectan la misma ausencia al mismo tiempo).
    const id = await obtenerOCrearSubcuentaPorNombre(businessId, nombre, tipo);
    // Nunca se cachea un error como si fuera un id válido: si obtenerOCrearSubcuentaPorNombre o
    // obtenerOCrearSubcuentaBajoMayorConocida lanzan, la línea nunca llega a completarse, así que
    // una resolución fallida jamás queda registrada como si hubiera tenido éxito.
    cacheSubRealizacion[key] = id;
    return id;
  };
  const { data: facturasProv } = await conDesde(sb.from('fz_proveedores').select('*').eq('business_id', businessId).lte('fecha', hastaFecha));
  const facturasProvMapGlobal = Object.fromEntries((facturasProv||[]).map(f => [f.id, f]));
  for (const f of (facturasProv||[])) {
    if (f.origen_poliza_id) continue; // ya se contabilizó como provisión en Pólizas
    // Mismo patrón exacto que ya usa Clientes: el documento/CxP conserva su moneda original y TC
    // histórico (fz_proveedores.moneda/tipo_cambio, sin tocar), pero la contabilidad SIEMPRE se
    // expresa en MXN multiplicando por ese TC. Para MXN, tc=1 y el resultado es idéntico a antes.
    const tc = Number(f.tipo_cambio) || 1;
    const base = { modulo: 'Factura de Proveedor', tipoOrigen: 'factura_proveedor', id: f.id, fecha: f.fecha, referencia: `${f.factura || 's/f'}${f.moneda && f.moneda!=='MXN'?` (${f.moneda} ${fmt(f.importe)} @ TC ${tc})`:''}`, detalle: f.proveedor || '' };
    desgloseLineas(f.desglose).forEach(linea => push({ ...base, cuenta: nombreSub(linea.subcuenta_id) }, 'sub:'+linea.subcuenta_id, tipoDeSub(linea.subcuenta_id), (Number(linea.monto)||0) * tc, 0));
    if (f.aplica_iva && Number(f.iva_monto)) {
      if (esRealizacionActiva(f.fecha)) { const id = await subRealizacion('IVA Acreditable — Pendiente de pago', 'activo'); push({ ...base, cuenta: 'IVA Acreditable — Pendiente de pago' }, 'sub:'+id, 'activo', (Number(f.iva_monto)) * tc, 0); }
      else push({ ...base, cuenta: 'IVA Acreditable' }, 'iva_acreditable', 'activo', (Number(f.iva_monto)) * tc, 0);
    }
    if (f.aplica_retencion && Number(f.retencion_isr_monto)) {
      const cat = f.retencion_categoria||'Sin categoría';
      if (esRealizacionActiva(f.fecha)) { const id = await subRealizacion(`Retención ISR — ${cat} — Pendiente de pago`, 'pasivo'); push({ ...base, cuenta: `Retención ISR — ${cat} — Pendiente de pago` }, 'sub:'+id, 'pasivo', 0, (Number(f.retencion_isr_monto)) * tc); }
      else push({ ...base, cuenta: `Retención ISR — ${cat}` }, 'ret_isr:'+cat, 'pasivo', 0, (Number(f.retencion_isr_monto)) * tc);
    }
    if (f.aplica_retencion && Number(f.retencion_iva_monto)) {
      const cat = f.retencion_categoria||'Sin categoría';
      if (esRealizacionActiva(f.fecha)) { const id = await subRealizacion(`Retención IVA — ${cat} — Pendiente de pago`, 'pasivo'); push({ ...base, cuenta: `Retención IVA — ${cat} — Pendiente de pago` }, 'sub:'+id, 'pasivo', 0, (Number(f.retencion_iva_monto)) * tc); }
      else push({ ...base, cuenta: `Retención IVA — ${cat}` }, 'ret_iva:'+cat, 'pasivo', 0, (Number(f.retencion_iva_monto)) * tc);
    }
    push({ ...base, cuenta: 'Proveedores' }, 'proveedores', 'pasivo', 0, (Number(f.importe)||0) * tc);
  }

  // 3. Facturas de Clientes — Dr Clientes, Cr [líneas] + Cr IVA Trasladado.
  // Moneda extranjera: el reconocimiento contable siempre es en MXN (moneda funcional), usando
  // el tipo de cambio de reconocimiento — el importe/moneda original se conserva en la propia
  // factura para trazabilidad, nunca se pierde, solo no se usa directo para la cuenta Clientes.
  const { data: facturasCli } = await conDesde(sb.from('fz_facturas_clientes').select('*').eq('business_id', businessId).lte('fecha', hastaFecha));
  const facturasCliMapGlobal = Object.fromEntries((facturasCli||[]).map(f => [f.id, f]));
  if ((facturasCli||[]).length) {
    const { data: lineasCli } = await sb.from('fz_facturas_clientes_lineas').select('*').in('factura_id', facturasCli.map(f=>f.id));
    for (const f of facturasCli) {
      const tc = Number(f.tipo_cambio) || 1;
      const base = { modulo: 'Factura de Cliente', tipoOrigen: 'factura_cliente', id: f.id, fecha: f.fecha, referencia: `Folio #${f.folio}${f.moneda==='USD'?` (USD ${fmt(f.total)} @ TC ${tc})`:''}`, detalle: nombreCliente(f.cliente_id) };
      push({ ...base, cuenta: 'Clientes' }, 'clientes', 'activo', (Number(f.total)||0) * tc, 0);
      (lineasCli||[]).filter(l=>l.factura_id===f.id).forEach(l => push({ ...base, cuenta: nombreSub(l.subcuenta_id) }, 'sub:'+l.subcuenta_id, tipoDeSub(l.subcuenta_id), 0, (Number(l.importe)||0) * tc));
      if (f.aplica_iva && Number(f.iva_monto)) {
        if (esRealizacionActiva(f.fecha)) { const id = await subRealizacion('IVA Trasladado — Pendiente de cobro', 'pasivo'); push({ ...base, cuenta: 'IVA Trasladado — Pendiente de cobro' }, 'sub:'+id, 'pasivo', 0, (Number(f.iva_monto)||0) * tc); }
        else push({ ...base, cuenta: 'IVA Trasladado' }, 'iva_trasladado', 'pasivo', 0, (Number(f.iva_monto)||0) * tc);
      }
    }
  }

  // 4. Movimientos de Bancos y Efectivo — cada movimiento, individualmente, siempre cuadra por
  // construcción (mismo monto en ambos lados). Los traspasos se revisan aparte, por pares
  // (misma traspaso_id, dos movimientos en tablas distintas) porque ahí sí puede haber diferencia
  // real si el tipo de cambio usado en cada lado no fue idéntico.
  const { data: todosCobrosAplicados } = await sb.from('fz_cobros_aplicados').select('*').eq('business_id', businessId).lte('fecha', hastaFecha);
  const cobrosPorOrigen = {};
  (todosCobrosAplicados||[]).forEach(c => { const k = `${c.origen_tabla}|${c.origen_id}`; (cobrosPorOrigen[k] = cobrosPorOrigen[k]||[]).push(c); });
  const { data: todosPagosAplicados } = await sb.from('fz_pagos_aplicados').select('*').eq('business_id', businessId).lte('fecha', hastaFecha);
  const pagosPorOrigen = {};
  (todosPagosAplicados||[]).forEach(p => { const k = `${p.origen_tabla}|${p.origen_id}`; (pagosPorOrigen[k] = pagosPorOrigen[k]||[]).push(p); });

  const { data: todasAplicacionesFiscales } = await sb.from('fz_aplicaciones_pago_fiscal').select('*').eq('business_id', businessId).lte('fecha', hastaFecha).is('revertido_at', null);
  const aplicacionesFiscalesPorOrigen = {};
  (todasAplicacionesFiscales||[]).forEach(a => { const k = `${a.origen_tabla}|${a.origen_id}`; (aplicacionesFiscalesPorOrigen[k] = aplicacionesFiscalesPorOrigen[k]||[]).push(a); });
  const idsPagosImpuestoNecesarios = [...new Set((todasAplicacionesFiscales||[]).map(a=>a.pago_impuesto_id))];
  const { data: pagosImpuestoRefs } = idsPagosImpuestoNecesarios.length ? await sb.from('fz_pagos_impuestos').select('id,tipo_impuesto,concepto').in('id', idsPagosImpuestoNecesarios) : { data: [] };
  const pagoImpuestoMapGlobal = Object.fromEntries((pagosImpuestoRefs||[]).map(p=>[p.id,p]));
  // Se resuelven de antemano las subcuentas de cada obligación fiscal que pudiera pagarse — el
  // mismo nombre/cuenta que ya usa el resto del motor de realización, para que compartan clave.
  const subcuentaObligacionCache = {};
  for (const p of (pagosImpuestoRefs||[])) {
    const obligacion = cuentaObligacionPago(p);
    if (obligacion && !subcuentaObligacionCache[obligacion.nombre]) {
      subcuentaObligacionCache[obligacion.nombre] = await subRealizacion(obligacion.nombre, obligacion.naturaleza);
    }
  }
  const CUENTA_ACTUALIZACION_FISCAL = 'Actualización fiscal';
  const CUENTA_RECARGOS_FISCALES = 'Recargos fiscales';
  const CUENTA_REDONDEO_FISCAL = 'Diferencias por redondeo fiscal';
  const CUENTA_PAGOS_POR_ACLARAR = 'Pagos por aclarar';
  if ((todasAplicacionesFiscales||[]).some(a => Number(a.monto_actualizacion) > 0.004)) subcuentaObligacionCache[CUENTA_ACTUALIZACION_FISCAL] = await subRealizacion(CUENTA_ACTUALIZACION_FISCAL, 'gasto');
  if ((todasAplicacionesFiscales||[]).some(a => Number(a.monto_recargos) > 0.004)) subcuentaObligacionCache[CUENTA_RECARGOS_FISCALES] = await subRealizacion(CUENTA_RECARGOS_FISCALES, 'gasto');
  if ((todasAplicacionesFiscales||[]).some(a => Math.abs(Number(a.monto_redondeo)) > 0.004)) subcuentaObligacionCache[CUENTA_REDONDEO_FISCAL] = await subRealizacion(CUENTA_REDONDEO_FISCAL, 'gasto');
  // Activo circulante / Deudores diversos — cuenta transitoria: la porción de un pago conjunto
  // que se queda sin aplicación al revertir una de sus aplicaciones NUNCA entra a resultados,
  // porque el dinero sí salió del banco — se queda "por aclarar" hasta que se reasigne.
  subcuentaObligacionCache[CUENTA_PAGOS_POR_ACLARAR] = await subRealizacion(CUENTA_PAGOS_POR_ACLARAR, 'activo');

  const procesarMovimientos = (movs, esBanco, tipoOrigenTag, moduloTag, tablaOrigenNombre) => {
    (movs||[]).forEach(m => {
      const claveOrigenCuenta = esBanco ? 'banco:'+m.cuenta_id : 'efectivo:'+m.moneda_id;
      const nombreOrigenCuenta = esBanco ? `Banco: ${nombreBanco(m.cuenta_id)}` : `Efectivo: ${nombreMoneda(m.moneda_id)}`;
      const base = { modulo: moduloTag, tipoOrigen: tipoOrigenTag, id: m.id, fecha: m.fecha, referencia: m.concepto || m.descripcion || 's/ref', detalle: m.proveedor || m.descripcion || '', cuentaId: m.cuenta_id, monedaId: m.moneda_id };
      if (Number(m.cargos)) {
        if (m.tipo_salida === 'impuesto') {
          // Caso especial: la contraparte no es UNA cuenta, son tantas como obligaciones cubra
          // este movimiento — se leen directo de sus aplicaciones fiscales reales, nunca de un
          // texto ni de un supuesto — así nunca se vuelve a representar la salida de banco/
          // efectivo por separado en una póliza aparte.
          const aplicacionesDeEste = aplicacionesFiscalesPorOrigen[`${tablaOrigenNombre}|${m.id}`] || [];
          if (aplicacionesDeEste.length) {
            aplicacionesDeEste.forEach(ap => {
              const pagoImp = pagoImpuestoMapGlobal[ap.pago_impuesto_id];
              const obligacion = pagoImp ? cuentaObligacionPago(pagoImp) : null;
              const cuenta = obligacion ? obligacion.nombre : 'Sin clasificar (revisar)';
              const clave = obligacion ? 'sub:'+subcuentaObligacionCache[obligacion.nombre] : 'sin_clasificar';
              const tipoCta = obligacion ? obligacion.naturaleza : 'gasto';
              // Aplicaciones de antes de este desglose (las 3 columnas en 0 pese a tener monto):
              // todo su monto ya era principal en su momento — mismo respaldo que el resto del
              // motor, para no alterar los pagos ya probados.
              const desglosado = Number(ap.monto_principal||0) + Number(ap.monto_actualizacion||0) + Number(ap.monto_recargos||0) + Math.abs(Number(ap.monto_redondeo||0));
              if (desglosado <= 0.004) {
                push({ ...base, cuenta }, clave, tipoCta, Number(ap.monto), 0);
              } else {
                if (Number(ap.monto_principal) > 0.004) push({ ...base, cuenta }, clave, tipoCta, Number(ap.monto_principal), 0);
                if (Number(ap.monto_actualizacion) > 0.004) push({ ...base, cuenta: CUENTA_ACTUALIZACION_FISCAL }, 'sub:'+subcuentaObligacionCache[CUENTA_ACTUALIZACION_FISCAL], 'gasto', Number(ap.monto_actualizacion), 0);
                if (Number(ap.monto_recargos) > 0.004) push({ ...base, cuenta: CUENTA_RECARGOS_FISCALES }, 'sub:'+subcuentaObligacionCache[CUENTA_RECARGOS_FISCALES], 'gasto', Number(ap.monto_recargos), 0);
                // Redondeo SAT: positivo (se pagó más) = Debe; negativo (se pagó menos) = Haber.
                // Una sola cuenta, con cargo o abono según el sentido — nunca siempre gasto.
                if (Number(ap.monto_redondeo) > 0.004) push({ ...base, cuenta: CUENTA_REDONDEO_FISCAL }, 'sub:'+subcuentaObligacionCache[CUENTA_REDONDEO_FISCAL], 'gasto', Number(ap.monto_redondeo), 0);
                else if (Number(ap.monto_redondeo) < -0.004) push({ ...base, cuenta: CUENTA_REDONDEO_FISCAL }, 'sub:'+subcuentaObligacionCache[CUENTA_REDONDEO_FISCAL], 'gasto', 0, Math.abs(Number(ap.monto_redondeo)));
              }
            });
            // Si alguna aplicación de este movimiento fue revertida, la suma de las vigentes ya
            // no cubre el total del cargo real — el hueco se hace VISIBLE en "Sin clasificar",
            // nunca se oculta ni se compensa con una póliza de ajuste.
            const totalAplicado = aplicacionesDeEste.reduce((s,ap)=>s+Number(ap.monto||0),0);
            const huecoPorReversion = Number(m.cargos) - totalAplicado;
            if (Math.abs(huecoPorReversion) > 0.004) push({ ...base, cuenta: CUENTA_PAGOS_POR_ACLARAR }, 'sub:'+subcuentaObligacionCache[CUENTA_PAGOS_POR_ACLARAR], 'activo', huecoPorReversion, 0);
          } else {
            push({ ...base, cuenta: 'Sin clasificar (revisar)' }, 'sin_clasificar', 'gasto', Number(m.cargos), 0);
          }
          push({ ...base, cuenta: nombreOrigenCuenta }, claveOrigenCuenta, 'activo', 0, Number(m.cargos));
          return;
        }
        if (m.tipo_salida === 'proveedor') {
          const pagosParaEste = pagosPorOrigen[`${tablaOrigenNombre}|${m.id}`] || [];
          if (pagosParaEste.length) {
            pagosParaEste.forEach(p => {
              const fProv = facturasProvMapGlobal[p.factura_id];
              const tcOriginal = fProv ? (Number(fProv.tipo_cambio)||1) : 1;
              const tcReal = Number(p.tipo_cambio) || tcOriginal;
              const montoOriginal = Number(p.monto)||0;
              // Proveedores se cancela al TC HISTÓRICO (el mismo con el que se registró la
              // factura) — nunca al de liquidación, así la cuenta cierra exacto sin importar
              // cuánto cambió el TC entre la factura y el pago.
              push({ ...base, cuenta: 'Proveedores' }, 'proveedores', 'pasivo', montoOriginal * tcOriginal, 0);
              const diferencia = montoOriginal * (tcReal - tcOriginal);
              if (Math.abs(diferencia) > 0.004) {
                if (diferencia > 0) push({ ...base, cuenta: 'Pérdida Cambiaria' }, 'perdida_cambiaria', 'gasto', diferencia, 0);
                else push({ ...base, cuenta: 'Ganancia Cambiaria' }, 'ganancia_cambiaria', 'ingreso', 0, -diferencia);
              }
            });
          } else {
            // Pago sin registro en fz_pagos_aplicados — no debería pasar en el flujo normal; por
            // seguridad se liquida tal cual, sin inventar un tipo de cambio que no existe.
            push({ ...base, cuenta: 'Proveedores' }, 'proveedores', 'pasivo', Number(m.cargos), 0);
          }
          push({ ...base, cuenta: nombreOrigenCuenta }, claveOrigenCuenta, 'activo', 0, (m.equivalente_mxn_historico!==null && m.equivalente_mxn_historico!==undefined) ? Number(m.equivalente_mxn_historico) : Number(m.cargos));
          return;
        }
        let cuentaContraria = 'Sin clasificar (revisar)', claveContraria = 'sin_clasificar', tipoContraria = 'gasto';
        let subtotalContraria = Number(m.cargos);
        if (m.tipo_salida === 'gasto') {
          cuentaContraria = nombreSub(m.subcuenta_id); claveContraria = 'sub:'+m.subcuenta_id; tipoContraria = tipoDeSub(m.subcuenta_id);
          subtotalContraria = m.aplica_iva ? (Number(m.subtotal)||0) : Number(m.cargos);
        }
        else if (m.tipo_salida === 'cliente') { cuentaContraria = 'Clientes'; claveContraria = 'clientes'; tipoContraria = 'activo'; }
        else if (m.tipo_salida === 'traspaso') { cuentaContraria = 'Traspasos entre cuentas'; claveContraria = 'traspasos'; tipoContraria = 'activo'; }
        push({ ...base, cuenta: cuentaContraria }, claveContraria, tipoContraria, subtotalContraria, 0);
        if (m.tipo_salida === 'gasto' && m.aplica_iva && Number(m.iva_monto)) push({ ...base, cuenta: 'IVA Acreditable' }, 'iva_acreditable', 'activo', Number(m.iva_monto), 0);
        push({ ...base, cuenta: nombreOrigenCuenta }, claveOrigenCuenta, 'activo', 0, Number(m.cargos));
      }
      if (Number(m.depositos)) {
        // El Banco se contabiliza en MXN real. Si el movimiento ya tiene su snapshot histórico
        // congelado (equivalente_mxn_historico, generado por el punto de guardado corregido),
        // se usa TAL CUAL — nunca se recalcula con datos que pudieron cambiar después. Solo los
        // movimientos ANTERIORES a esta corrección (sin ese campo) caen al cálculo en vivo previo,
        // para no alterar retroactivamente nada ya validado.
        let montoBancoMxn = Number(m.depositos);
        if (m.equivalente_mxn_historico !== null && m.equivalente_mxn_historico !== undefined) {
          montoBancoMxn = Number(m.equivalente_mxn_historico);
        } else if (m.tipo_entrada === 'cliente') {
          const cobrosParaBanco = cobrosPorOrigen[`${tablaOrigenNombre}|${m.id}`] || [];
          if (cobrosParaBanco.length) {
            montoBancoMxn = cobrosParaBanco.reduce((s,c) => {
              const f = facturasCliMapGlobal[c.factura_id];
              const tcOriginal = f ? (Number(f.tipo_cambio)||1) : 1;
              const tcReal = Number(c.tipo_cambio) || tcOriginal;
              return s + (Number(c.monto)||0) * tcReal;
            }, 0);
          }
        }
        push({ ...base, cuenta: nombreOrigenCuenta }, claveOrigenCuenta, 'activo', montoBancoMxn, 0);
        if (m.tipo_entrada === 'cliente') {
          const cobros = cobrosPorOrigen[`${tablaOrigenNombre}|${m.id}`] || [];
          if (cobros.length) {
            cobros.forEach(c => {
              const f = facturasCliMapGlobal[c.factura_id];
              const tcOriginal = f ? (Number(f.tipo_cambio)||1) : 1;
              const tcReal = Number(c.tipo_cambio) || tcOriginal;
              const montoOriginal = Number(c.monto)||0;
              // Clientes se liquida al TC de RECONOCIMIENTO (el mismo con el que se registró la
              // factura) — así la cuenta siempre cierra exacto, sin importar cuánto cambió el TC.
              push({ ...base, cuenta: 'Clientes' }, 'clientes', 'activo', 0, montoOriginal * tcOriginal);
              const diferencia = montoOriginal * (tcReal - tcOriginal);
              if (Math.abs(diferencia) > 0.004) {
                if (diferencia > 0) push({ ...base, cuenta: 'Ganancia Cambiaria' }, 'ganancia_cambiaria', 'ingreso', 0, diferencia);
                else push({ ...base, cuenta: 'Pérdida Cambiaria' }, 'perdida_cambiaria', 'gasto', -diferencia, 0);
              }
            });
          } else {
            // Cobro sin registro en fz_cobros_aplicados — no debería pasar en el flujo normal;
            // por seguridad se liquida tal cual, sin inventar un tipo de cambio que no existe.
            push({ ...base, cuenta: 'Clientes' }, 'clientes', 'activo', 0, Number(m.depositos));
          }
        } else if (m.tipo_entrada === 'traspaso') {
          push({ ...base, cuenta: 'Traspasos entre cuentas' }, 'traspasos', 'activo', 0, Number(m.depositos));
        } else {
          push({ ...base, cuenta: 'Sin clasificar (revisar)' }, 'sin_clasificar', 'gasto', 0, Number(m.depositos));
        }
      }
    });
  };
  const [bancosMovQ, efvoMovQ] = await Promise.all([
    conDesde(sb.from('fz_bancos_mov').select('*').eq('business_id', businessId).lte('fecha', hastaFecha)),
    conDesde(sb.from('fz_efectivo_mov').select('*').eq('business_id', businessId).lte('fecha', hastaFecha)),
  ]);
  procesarMovimientos(bancosMovQ.data, true, 'banco_mov', 'Movimiento de Banco', 'fz_bancos_mov');
  procesarMovimientos(efvoMovQ.data, false, 'efectivo_mov', 'Movimiento de Efectivo', 'fz_efectivo_mov');

  // Traspasos por pares (misma traspaso_id, en cualquiera de las 2 tablas) — aquí sí puede
  // haber una diferencia real y legítima si el monto destino no fue idéntico al monto origen.
  const traspasos = [
    ...(bancosMovQ.data||[]).filter(m=>m.traspaso_id).map(m=>({...m, _tabla:'fz_bancos_mov', _cuenta:`Banco: ${nombreBanco(m.cuenta_id)}`})),
    ...(efvoMovQ.data||[]).filter(m=>m.traspaso_id).map(m=>({...m, _tabla:'fz_efectivo_mov', _cuenta:`Efectivo: ${nombreMoneda(m.moneda_id)}`})),
  ];
  const traspasoGrupos = {};
  traspasos.forEach(m => { (traspasoGrupos[m.traspaso_id] = traspasoGrupos[m.traspaso_id] || []).push(m); });

  return { filas, traspasoGrupos, polizas: polizaMap, mayores, subcuentas };
}

// Agrupa por documento de origen y busca cuáles no cuadran internamente (Cargo ≠ Abono dentro
// del mismo documento). Si no encuentra ninguno así, revisa los pares de traspaso. Si tampoco,
// dice honestamente que no pudo aislar un origen único — nunca inventa uno.
async function diagnosticarDescuadreBalanza(businessId, hastaFecha) {
  const { filas, traspasoGrupos } = await getLibroPartidaDobleConOrigen(businessId, hastaFecha);
  const grupos = {};
  filas.forEach(f => {
    const key = f.tipoOrigen + ':' + f.id;
    if (!grupos[key]) grupos[key] = { modulo: f.modulo, tipoOrigen: f.tipoOrigen, id: f.id, fecha: f.fecha, referencia: f.referencia, detalle: f.detalle, cuentaId: f.cuentaId, monedaId: f.monedaId, lineas: [], cargo: 0, abono: 0 };
    grupos[key].lineas.push({ cuenta: f.cuenta, cargo: f.cargo, abono: f.abono });
    grupos[key].cargo += f.cargo;
    grupos[key].abono += f.abono;
  });
  const documentosDescuadrados = Object.values(grupos).filter(g => Math.abs(g.cargo - g.abono) > 0.001);

  const paresTraspasoDescuadrados = [];
  Object.entries(traspasoGrupos).forEach(([traspasoId, movs]) => {
    if (movs.length < 2) return; // par incompleto — no se puede comparar, se omite (no se inventa)
    const totalCargo = movs.reduce((s,m)=>s+(Number(m.cargos)||0),0);
    const totalDeposito = movs.reduce((s,m)=>s+(Number(m.depositos)||0),0);
    if (Math.abs(totalCargo - totalDeposito) > 0.001) {
      paresTraspasoDescuadrados.push({ traspasoId, movs, diferencia: totalCargo - totalDeposito });
    }
  });

  return { documentosDescuadrados, paresTraspasoDescuadrados };
}

// Mapea el tipoOrigen del diagnóstico al formato que ya entiende abrirOrigenDesdeDetalle,
// para reutilizar la misma navegación "Ver documento" que ya existe en otras pantallas.
function verDocumentoDesdeOrigen(item, businessId) {
  const mapa = {
    poliza: { tipo: 'poliza', id: item.id },
    factura_proveedor: { tipo: 'proveedor', id: item.id, fecha: item.fecha },
    factura_cliente: { tipo: 'factura_cliente', id: item.id, fecha: item.fecha },
    banco_mov: { tipo: 'bancos', id: item.id, cuentaId: item.cuentaId, fecha: item.fecha },
    efectivo_mov: { tipo: 'efectivo', id: item.id, monedaId: item.monedaId, fecha: item.fecha },
  };
  const origen = mapa[item.tipoOrigen];
  if (!origen) { toast('No se puede abrir este documento directamente.', 'error'); return; }
  document.getElementById('modalDiagnosticoDescuadre').classList.remove('show');
  abrirOrigenDesdeDetalle(origen, businessId);
}

